// The handbook lives in git, not on the n8n host, so ingestion pulls the
// published copy. Re-running re-indexes from whatever is currently on main.
const BASE = 'https://raw.githubusercontent.com/sherzodibodullayev/upwork_case_2/main/kb/';
const DOCS = [
  '01-device-and-equipment-policy',
  '02-support-tiers-and-sla',
  '03-remote-work-policy',
  '04-remote-access-policy',
  '05-security-incident-response',
  '06-onboarding-and-offboarding',
  '07-software-and-procurement',
  '08-data-classification-and-retention',
];
return DOCS.map(doc => ({ json: { doc, url: BASE + doc + '.md' } }));

// Carry the document name alongside the text so it survives into chunk
// metadata. Without it a retrieved chunk cannot be cited.
return $input.all().map((item, i) => ({
  json: {
    doc: $('List documents').all()[i].json.doc,
    text: item.json.data,
  },
}));

const id = 'TKT-' + Math.floor(100000 + Math.random() * 899999);
const sla = { S1: '15 minutes', S2: '1 business hour', S3: '4 business hours', S4: '1 business day' };
const sev = (query.match(/\bS[1-4]\b/i) || ['S3'])[0].toUpperCase();
return JSON.stringify({ ticket_id: id, severity: sev, first_response_due: sla[sev], summary: query });

const id = 'BKG-' + Math.floor(1000 + Math.random() * 8999);
const d = new Date(Date.now() + 24 * 3600 * 1000);
d.setUTCHours(14, 0, 0, 0);
return JSON.stringify({ booking_id: id, slot: d.toISOString(), duration_minutes: 45, channel: 'video call', topic: query });
